async function fixture(deferred=false,options:Parameters<typeof workFixture>[0]={}){const f=await workFixture(options);try{
 const expense=await f.made('finance/accounts',{code:'PROFIT-EXP',name:'Synthetic operating costs',kind:'expense',operationalRole:'expense',hubId:f.hub,currencyId:f.currency.id,currencyVersion:1,reason:'Explicit cost account'}),liability=await f.made('finance/accounts',{code:'PROFIT-DUE',name:'Synthetic payable',kind:'liability',operationalRole:'payable',hubId:f.hub,currencyId:f.currency.id,currencyVersion:1,reason:'Explicit payable'}),engagement=await f.create({components:[{...f.components[0],earningBasis:'calendar_days'}]});assert.equal(engagement.response.status,201,JSON.stringify(engagement.body));
 const service=await f.made('payroll/pay-periods',{engagementId:engagement.body.data.id,workVersion:1,code:'JAN',definition:{from:'2026-01-01',through:'2026-01-31',payOn:'2026-02-15',active:true,timingReview:'PRIVATE service period'},reason:'PRIVATE period review'}),salary=await f.made('payroll/salary-accruals',{period:{id:f.period.id,version:1},expenseAccount:{id:expense.id,version:1},liabilityAccount:{id:liability.id,version:1},postedOn:'2026-01-31',servicePeriod:{id:service.id,version:1},componentCode:'ADMIN',reference:'PRIVATE-SALARY',earningReview:'PRIVATE salary service',taxReview:'PRIVATE employment review',reason:'PRIVATE approval'});
 const invoice=await f.issue(deferred?{}:{recognition:'earned',accounts:{...f.base.accounts,consideration:{id:f.income.id,version:1}}});assert.equal(invoice.response.status,201,JSON.stringify(invoice.body));
 const bill=await f.made('finance/expense-bills',{payee:{id:f.payee.id,version:1},currency:{id:f.currency.id,version:1},payableAccount:{id:liability.id,version:1},documentNumber:'PRIVATE COST',issuedOn:'2026-11-07',dueOn:'2026-12-07',postedOn:'2026-11-07',period:{id:f.period.id,version:1},lines:[{description:'PRIVATE learner costs',hubId:f.hub,classId:f.c.id,studentId:f.student.id,expenseAccount:{id:expense.id,version:1},taxAccount:null,taxCode:{id:f.planInput.taxCodeId,version:1},taxOn:'2026-11-07',amount:'100',pricing:'tax_exclusive',recoverablePercent:'0',taxReview:'PRIVATE explicit tax review'}],missingEvidenceReason:'Synthetic missing receipt',reason:'PRIVATE cost approval'});
 const manualInput={periodId:f.period.id,periodVersion:1,postedOn:'2026-11-07',description:'PRIVATE manual source',reference:'PRIVATE reference',reason:'PRIVATE review',lines:[{accountId:f.cash.id,accountVersion:1,side:'debit',amount:'70.03'},{accountId:expense.id,accountVersion:1,side:'debit',amount:'30.02'},{accountId:f.income.id,accountVersion:1,side:'credit',amount:'100.05'}]},manual=await f.made('finance/journals',manualInput);
 const targets=[{hubId:f.hub,classId:f.c.id,studentId:f.student.id,weight:1},{hubId:f.hub,classId:null,studentId:null,weight:2}],split=async()=>{for(const [path,lines] of [['payroll/journals/'+salary.id+'/cost-attribution',[{lineNumber:1,targets}]],['finance/expense-bills/'+bill.id+'/cost-allocation',[{lineNumber:1,targets}]],['finance/journals/'+manual.id+'/attribution',[{lineNumber:2,targets},{lineNumber:3,targets}]]] as const){const r=await f.request(path,{expectedVersion:0,lines,reason:'PRIVATE reviewed analytical assignment'});assert.equal(r.response.status,200,JSON.stringify(r.body));}};
 const report=(params:Record<string,string>=range,as='master')=>f.request('reports/finance/profitability?'+new URLSearchParams(params),undefined,as);
 return {...f,expense,liability,salary,invoice:invoice.body.data,bill,manual,manualInput,targets,split,report};
 }catch(error){await f.pg.close();throw error;}}
