check('one actual concurrent posting cannot split the consolidated report source and ledger snapshot',async f=>{
 const runtime=f.pg.runtime!,connect=runtime.connect.bind(runtime);let reached!:()=>void,release!:()=>void,reads=0,pending:ReturnType<typeof f.report>|undefined;const ready=new Promise<void>(r=>reached=r),gate=new Promise<void>(r=>release=r);
 runtime.connect=async()=>{const c=await connect();return {async query<Row>(sql:string,params?:unknown[]){const result=await c.query<Row>(sql,params);if(sql.startsWith('WITH baseline_tuition')){reads++;reached();await gate;}return result;},release(destroy?:boolean){c.release(destroy);}};};
 try{pending=f.report();await Promise.race([ready,delay(2000).then(()=>{throw new Error('PROFITABILITY_SNAPSHOT_NOT_CAPTURED');})]);const posted=await f.request('finance/journals',{...f.manualInput,reference:'CONCURRENT',lines:[{accountId:f.cash.id,accountVersion:1,side:'debit',amount:'1'},{accountId:f.income.id,accountVersion:1,side:'credit',amount:'1'}]});assert.equal(posted.response.status,201,JSON.stringify(posted.body));release();const r=await pending;assert.equal(r.response.status,200);assert.equal(reads,1);assert.equal(r.body.data.currencies[0].income.minor,'20005');assert.equal(r.body.data.ledgerReconciliation[0].postedIncome.minor,'20005');assert.equal(r.body.data.ledgerReconciliation[0].moneyReconciles,true);runtime.connect=connect;assert.equal((await f.report()).body.data.currencies[0].income.minor,'20105');}finally{release();runtime.connect=connect;await Promise.allSettled([pending].filter(Boolean));}
},true);
check('profitability keeps old account precision and huge values exact across separate currencies',async f=>{
 assert.equal((await f.request('finance/currencies/'+f.currency.id+'/change',{expectedVersion:1,unitScale:3,reason:'Synthetic precision change'})).response.status,200);
 const account=async(code:string,currencyId:string,currencyVersion:number,kind:string)=>f.made('finance/accounts',{code,name:'Synthetic precision account',kind,operationalRole:kind==='income'?'revenue':'cash',hubId:f.hub,currencyId,currencyVersion,reason:'Explicit precision mapping'}),cash=await account('CAD-NEW-CASH',f.currency.id,2,'asset'),income=await account('CAD-NEW-INCOME',f.currency.id,2,'income'),usd=await f.made('finance/currencies',{code:'USD',name:'US dollar',unitScale:2,reason:'Separate currency'}),usdCash=await account('USD-CASH',usd.id,1,'asset'),usdIncome=await account('USD-INCOME',usd.id,1,'income');
 for(const [a,b,amount]of [[cash,income,'0.005'],[usdCash,usdIncome,'123456789012345678901234567890.12']] as const)assert.equal((await f.request('finance/journals',{...f.manualInput,lines:[{accountId:a.id,accountVersion:1,side:'debit',amount},{accountId:b.id,accountVersion:1,side:'credit',amount}]})).response.status,201);
 const r=await f.report();assert.equal(r.response.status,200,JSON.stringify(r.body));const d=r.body.data,cad=d.currencies.find((c:any)=>c.currencyId===f.currency.id),other=d.currencies.find((c:any)=>c.currencyId===usd.id);assert.equal(cad.unitScale,3);assert.equal(cad.income.amount,'200.055');assert.equal(cad.expenses.amount,'3143.020');assert.equal(other.income.amount,'123456789012345678901234567890.12');assert.equal(other.unitScale,2);assert.equal(d.ledgerReconciliation.length,2);assert.ok(d.ledgerReconciliation.every((r:any)=>r.moneyReconciles));assert.equal(d.currencyConversion,'none');assert.equal(d.grandTotal,undefined);assert.equal((await f.report({...range,currencyIds:usd.id})).body.data.currencies.length,1);
});
