check('a compiled restricted daemon generates one consolidated private file without an API tick or provider call',async f=>{
 await f.split();await reader(f);const q=await f.request('reports/jobs',{reportId:'finance.profitability',parameters:{...range,attributionBasis:'reviewed',studentIds:f.student.id}},'manager');assert.equal(q.response.status,202);const database=(await f.pg.query<{name:string}>('SELECT current_database() name')).rows[0].name;assert.match(database,/^kavosh_test_[a-f0-9]{32}$/);const login='kavosh_profit_'+randomUUID().replaceAll('-',''),password='synthetic_only_'+randomUUID().replaceAll('-','');let child:ReturnType<typeof spawn>|undefined;try{await f.pg.exec(`CREATE ROLE ${login} LOGIN NOSUPERUSER NOCREATEROLE NOCREATEDB NOREPLICATION NOBYPASSRLS PASSWORD '${password}';GRANT kavosh_automation_worker TO ${login}`);const url=new URL(process.env.TEST_DATABASE_URL!);url.username=login;url.password=password;url.pathname='/'+database;let output='';const command=process.env.REPORT_WORKER_COMPILED_ENTRY?[process.env.REPORT_WORKER_COMPILED_ENTRY]:['--import','tsx','scripts/process-reports.ts'];child=spawn(process.execPath,command,{cwd:process.cwd(),env:{PATH:process.env.PATH,NODE_ENV:'test',DATABASE_SSL_MODE:'disable',REPORT_WORKER_ENABLED:'true',REPORT_SCHEDULER_ENABLED:'false',REPORT_WORKER_DATABASE_URL:url.toString(),REPORT_WORKER_ACADEMIES:JSON.stringify([f.a])},stdio:['ignore','ignore','pipe']});child.stderr?.on('data',b=>{if(output.length<2000)output+=String(b).slice(0,2000-output.length);});const start=performance.now(),deadline=start+8000;let done=false;while(performance.now()<deadline){done=(await f.pg.query('SELECT 1 FROM public.report_jobs WHERE id=$1 AND status=\'succeeded\'',[q.body.data.id])).rows.length===1;if(done||child.exitCode!==null)break;await delay(40);}assert.ok(done,'Consolidated daemon did not complete: '+output);const file=await f.request('reports/jobs/'+q.body.data.id+'/download',undefined,'manager');assert.equal(file.response.status,200);assert.equal(csv(file.body).find(r=>r.section==='currency_total'&&r.field==='payrollExpense')?.amount_minor,'100000');const exit=new Promise<number|null>(r=>child!.once('exit',r));child.kill('SIGTERM');assert.equal(await Promise.race([exit,delay(2000,undefined,{ref:false}).then(()=>-1)]),0);assert.doesNotMatch(output,/postgresql:|synthetic_only_|password|token_hash/i);console.log(JSON.stringify({consolidatedDaemonMs:Math.ceil(performance.now()-start),jobs:1,compiled:!!process.env.REPORT_WORKER_COMPILED_ENTRY,externalIO:false,productionSlo:false}));}finally{if(child&&child.exitCode===null){child.kill('SIGKILL');await new Promise(r=>child!.once('exit',r));}await f.pg.exec('DROP ROLE '+login);}
},true);
test('254 to255 preserves actual financial and report history plus preset function authority',async()=>{
 const f=await fixture(false,{throughSchema:254});try{const old=await f.made('reports/presets',{anchor:{kind:'hub',id:f.hub},definition:{name:'Historical operating ledger',reportId:'finance.profit-loss',parameters:range},reason:'Original saved definition'}),file=await f.request('reports/finance/profit-loss/export?'+new URLSearchParams(range));assert.equal(file.response.status,200);const snapshot=async()=>{const rows:unknown[]=[];for(const table of ['report_presets','report_preset_revisions','tuition_invoices','expense_bills','finance_journals','finance_journal_lines','payroll_salary_accruals','approval_requests','audit_events','outbox_events'])rows.push((await f.pg.query('SELECT to_jsonb(x) row FROM public.'+table+' x ORDER BY to_jsonb(x)::text')).rows);rows.push((await f.pg.query("SELECT oid,proowner,proacl,proconfig FROM pg_proc WHERE oid IN('public.report_preset_static_definition_valid(jsonb)'::regprocedure,'public.report_preset_definition_valid(jsonb)'::regprocedure) ORDER BY oid")).rows);return rows;},before=await snapshot();assert.equal((await f.pg.query('SELECT public.schema_revision() n')).rows[0].n,254);await f.pg.exec(await readFile(new URL('../db/migrations/255_consolidated_profitability_presets.sql',import.meta.url),'utf8'));assert.equal((await f.pg.query('SELECT public.schema_revision() n')).rows[0].n,255);assert.deepEqual(await snapshot(),before);const stable=(csv:string)=>csv.split('\r\n').filter(line=>!line.startsWith('"metadata","snapshotAt",'));assert.deepEqual(stable((await f.request('reports/finance/profit-loss/export?'+new URLSearchParams(range))).body),stable(file.body));assert.equal((await f.request('reports/presets/'+old.id+'/run')).response.status,200);await upgradeToCurrent(f.pg);const current=await f.report();assert.equal(current.response.status,200,JSON.stringify(current.body));assert.equal(current.body.data.ledgerReconciliation[0].moneyReconciles,true);}finally{await f.pg.close();}
});
